<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/club_rewards.php';
final class ClubRewardsTest extends TestCase {
 private function db():PDO {
  $p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA foreign_keys=ON');
  $p->exec("CREATE TABLE treneri(id INTEGER PRIMARY KEY,aktivni INT,jmeno TEXT,email TEXT);INSERT INTO treneri VALUES(1,1,'Test Coach','coach@example.invalid'),(2,1,'First Lead','lead@example.invalid'),(3,1,'Finance Person','finance@example.invalid'),(4,1,'Other Lead','other@example.invalid')");
  $p->exec("CREATE TABLE sportovci(id INTEGER PRIMARY KEY,jmeno TEXT,prijmeni TEXT,email TEXT);INSERT INTO sportovci VALUES(10,'Test','Athlete','athlete@example.invalid'),(20,'First','Lead','lead@example.invalid')");
  $p->exec("CREATE TABLE staff_user_positions(trainer_id INT,position_code TEXT);INSERT INTO staff_user_positions VALUES(1,'coach'),(2,'sports_lead'),(3,'finance_manager'),(4,'sports_lead')");$p->exec('CREATE TABLE staff_superadmins(trainer_id INT)');
  $p->exec('CREATE TABLE dalsi_cinnosti(id INTEGER PRIMARY KEY,trener_id INT,nazev TEXT,delka REAL,poznamka TEXT,datum TEXT)');
  foreach(['20261022220000_accounting_ledger','20261023020000_training_closure','20261023060000_club_rewards'] as $m){$migration=require dirname(__DIR__,2).'/migrations/'.$m.'.php';$migration['up']($p);self::assertTrue($migration['verify']($p));}
  $snapshot=['training_id'=>77,'participant_ids'=>[10,20],'coach_ids'=>[1],'description'=>'TEST actual training'];
  $q=$p->prepare("INSERT INTO training_closure_revisions(training_id,version,status,actual_date,actual_started_at,actual_ended_at,duration_minutes,snapshot_json,reason,closed_by) VALUES(77,1,'closed','2026-01-10','2026-01-10 10:00:00','2026-01-10 11:15:00',75,?,'TEST actual paper attendance',2)");$q->execute([json_encode($snapshot)]);$p->exec("INSERT INTO training_closures VALUES(77,1,1,'closed')");
  $this->as(2);clubRewardRule($p,['kind'=>'coach','unit'=>'hour','rate_minor'=>10000,'valid_from'=>'2026-01-01','valid_to'=>'2026-12-31','title'=>'TEST coach policy','approval_evidence'=>'TEST only signed decision','accounting_method'=>'TEST only accountant method'],2,'TEST explicitly approved rule',true);
  clubRewardRule($p,['kind'=>'athlete','unit'=>'training','rate_minor'=>1000,'valid_from'=>'2026-01-01','valid_to'=>'2026-12-31','title'=>'TEST athlete policy','approval_evidence'=>'TEST only signed decision','accounting_method'=>'TEST only accountant method'],2,'TEST explicitly approved rule',true);
  $this->as(3);accountingLedgerCreateAccount($p,['code'=>'TEST','name'=>'TEST cash','kind'=>'cash','opening_minor'=>100000,'opened_on'=>'2026-01-01','evidence'=>'TEST cash inventory'],3,'TEST opening count',true);return $p;
 }
 private function as(int $id):void {$pos=[1=>'coach',2=>'sports_lead',3=>'finance_manager',4=>'sports_lead'][$id];$_SESSION=['trener_id'=>$id,'staff_positions'=>[$pos],'staff_active_position'=>$pos];}
 private function submit(PDO $p,array $change=[]):array {$this->as(1);return clubRewardSubmit($p,array_replace(['kind'=>'coach','subject_id'=>1,'rule_id'=>1,'date_from'=>'2026-01-01','date_to'=>'2026-01-31','recipient_kind'=>'trainer','recipient_id'=>1,'recipient_evidence'=>'TEST own payee agreement','request_key'=>'TEST-claim-1'],$change),1,'TEST confirmed actual report',true);}
 private function approve(PDO $p,array $v,int $actor=2):void {$this->as($actor);clubRewardDecide($p,(int)$v['id'],'approved',$actor,'TEST independent approval',true);}
 private function movement(PDO $p,int $amount,string $ref):int {$this->as(3);return (int)accountingLedgerRecord($p,['account_id'=>1,'kind'=>$amount<0?'expense':'income','amount_minor'=>$amount,'currency'=>'CZK','effective_on'=>'2026-02-01','source_context'=>'TEST-cash','source_reference'=>$ref,'request_key'=>$ref,'evidence'=>'TEST signed cash proof'],3,'TEST actual cash movement',true)['id'];}
 private function pay(PDO $p,int $claim,int $movement,int $amount,string $key='TEST-pay-1'):array {$this->as(3);return clubRewardPay($p,$claim,['movement_id'=>$movement,'amount_minor'=>$amount,'paid_on'=>'2026-02-01','received_by'=>'TEST named receiver, signed receipt','request_key'=>$key],3,'TEST actual payout receipt',true);}
 private function denied(callable $f,string $text=''):void {try{$f();self::fail('Expected refusal');}catch(DomainException|AccountingLedgerException $e){self::assertNotSame('',$e->getMessage());if($text!=='')self::assertStringContainsString($text,$e->getMessage());}}
 protected function tearDown():void {$_SESSION=[];unset($GLOBALS['club_reward_allocation_context']);}
 public function testClosedActivityOnlyAndImmutableRetry():void {$p=$this->db();$v=$this->submit($p);self::assertSame(12500,(int)$v['amount_minor']);self::assertSame($v,$this->submit($p));$this->denied(fn()=>$this->submit($p,['recipient_evidence'=>'TEST different receiver proof']),'Klíč');self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM club_reward_claims')->fetchColumn());}
 public function testPartialPaymentExactlyOnceAndNoSyntheticMoney():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());$m=$this->movement($p,-13000,'TEST-bank-1');$pay=$this->pay($p,1,$m,5000);self::assertSame($pay,$this->pay($p,1,$m,5000));$this->pay($p,1,$m,7500,'TEST-pay-2');self::assertSame(12500,clubRewardPaid($p,1));$this->denied(fn()=>$this->pay($p,1,$m,1,'TEST-over'));self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());}
 public function testConcurrentLikeTwoRequestsCannotOverpay():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$m=$this->movement($p,-20000,'TEST-two');$this->pay($p,1,$m,10000);$this->denied(fn()=>$this->pay($p,1,$m,10000,'TEST-pay-second'));self::assertSame(10000,clubRewardPaid($p,1));}
 public function testSourceCorrectionKeepsApprovedVersionAndRequiresNewApproval():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$m=$this->movement($p,-12500,'TEST-full');$this->pay($p,1,$m,12500);$p->exec("UPDATE training_closures SET status='void'");self::assertTrue(clubRewardChanged($p,clubRewardClaim($p,1),$v));$this->denied(fn()=>$this->pay($p,1,$m,1,'TEST-after-change'));
  $new=$this->submit($p,['claim_id'=>1,'expected_version'=>1,'request_key'=>'TEST-correction']);self::assertSame(0,(int)$new['amount_minor']);self::assertSame(12500,(int)clubRewardVersion($p,1)['amount_minor']);$this->approve($p,$new);$incoming=$this->movement($p,12500,'TEST-return');$return=$this->pay($p,1,$incoming,12500,'TEST-return-payment');self::assertSame(-12500,(int)$return['amount_minor']);self::assertSame(0,clubRewardPaid($p,1));self::assertSame(2,(int)$p->query('SELECT COUNT(*) FROM club_reward_versions')->fetchColumn());}
 public function testSelfApprovalAndRevokedRoleDenied():void {$p=$this->db();$v=$this->submit($p);$this->as(1);$p->exec("INSERT INTO staff_user_positions VALUES(1,'sports_lead')");$_SESSION['staff_positions']=['sports_lead'];$_SESSION['staff_active_position']='sports_lead';$this->denied(fn()=>clubRewardDecide($p,(int)$v['id'],'approved',1,'TEST forbidden self approve',true),'Vlastní');$this->as(2);$p->exec('DELETE FROM staff_user_positions WHERE trainer_id=2');$this->denied(fn()=>clubRewardDecide($p,(int)$v['id'],'approved',2,'TEST revoked approval role',true),'neplatí');}
 public function testAthletePossibleSelfIdentityDeniedWithoutMerging():void {$p=$this->db();$this->as(4);$v=clubRewardSubmit($p,['kind'=>'athlete','subject_id'=>20,'rule_id'=>2,'date_from'=>'2026-01-01','date_to'=>'2026-01-31','recipient_kind'=>'person','recipient_id'=>20,'recipient_evidence'=>'TEST personal receiver','request_key'=>'TEST-athlete-self'],4,'TEST athlete submitted',true);$this->as(2);$this->denied(fn()=>clubRewardDecide($p,(int)$v['id'],'approved',2,'TEST forbidden athlete self',true),'Možná shoda');}
 public function testDirectLedgerAllocationCannotBypassRewardWorkflow():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$m=$this->movement($p,-12500,'TEST-bypass');$this->denied(fn()=>accountingLedgerAllocate($p,$m,'reward_claim',1,5000,'TEST-direct',3,'TEST generic route bypass',true),'nároku');self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM accounting_allocations')->fetchColumn());}
 public function testOverlapOldMissingSnapshotAndUnapprovedRateFailClosed():void {$p=$this->db();$this->submit($p);$this->denied(fn()=>$this->submit($p,['date_from'=>'2026-01-10','request_key'=>'TEST-overlap']),'překrývá');$this->denied(fn()=>$this->submit($p,['rule_id'=>999,'request_key'=>'TEST-no-rule']),'pravidlo');$p->exec("CREATE TABLE sportovec_obdobi(id INT,sportovec_id INT,datum_od TEXT,datum_do TEXT,vyplaceno INT);INSERT INTO sportovec_obdobi VALUES(1,10,'2026-01-01','2026-01-31',1)");$this->as(2);$this->denied(fn()=>clubRewardSubmit($p,['kind'=>'athlete','subject_id'=>10,'rule_id'=>2,'date_from'=>'2026-01-01','date_to'=>'2026-01-31','recipient_kind'=>'person','recipient_id'=>10,'recipient_evidence'=>'TEST athlete receiver','request_key'=>'TEST-old-period'],2,'TEST history must stay frozen',true),'historie');}
 public function testReturnedOtherWorkCanBeCorrectedButSubmittedCannot():void {$p=$this->db();$p->exec("INSERT INTO dalsi_cinnosti VALUES(1,1,'TEST prep',0.5,'TEST paper proof','2026-01-11')");$v=$this->submit($p);self::assertSame(17500,(int)$v['amount_minor']);$this->denied(fn()=>clubRewardAssertOtherWorkMutable($p,1,'2026-01-11'),'výkazu');$this->as(2);clubRewardDecide($p,(int)$v['id'],'returned',2,'TEST return for missing proof',true);clubRewardAssertOtherWorkMutable($p,1,'2026-01-11');self::assertSame(17500,(int)clubRewardVersion($p,(int)$v['id'])['amount_minor']);}
 public function testSourceChangedBeforeApprovalRejected():void {$p=$this->db();$v=$this->submit($p);$p->exec("UPDATE training_closures SET status='void'");$this->as(2);$this->denied(fn()=>clubRewardDecide($p,(int)$v['id'],'approved',2,'TEST stale source refusal',true),'Podklady');}
 public function testCoachCannotReadSubmitOtherPersonAndFinanceCannotApprove():void {$p=$this->db();$this->denied(fn()=>$this->submit($p,['subject_id'=>2]),'vlastní');$v=$this->submit($p);$this->as(3);$this->denied(fn()=>clubRewardDecide($p,(int)$v['id'],'approved',3,'TEST wrong position approval',true),'pozici');}
 public function testExportSeparatesClaimMoneyAndVersions():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$m=$this->movement($p,-5000,'TEST-export');$this->pay($p,1,$m,5000);$rows=clubRewardExportRows($p,'2026-01-01',date('Y-m-d'));self::assertSame(7500,$rows['claims'][0]['balance_minor']);self::assertSame(5000,$rows['claims'][0]['paid_minor']);self::assertCount(1,$rows['versions']);self::assertCount(1,$rows['payouts']);self::assertSame($m,(int)$rows['payouts'][0]['movement_id']);}
 public function testHistoricalExportDoesNotPretendLaterApprovalWasAlreadyKnown():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$rows=clubRewardExportRows($p,'2026-01-01','2026-01-31');self::assertSame(0,$rows['claims'][0]['approved_minor']);self::assertNull($rows['claims'][0]['approved_version_id']);self::assertCount(0,$rows['versions']);self::assertCount(0,$rows['decisions']);}
 public function testPendingCorrectiveVersionBlocksPaymentsUntilSeparateDecision():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$this->submit($p,['claim_id'=>1,'expected_version'=>1,'request_key'=>'TEST-pending-correction']);$m=$this->movement($p,-12500,'TEST-pending-movement');$this->denied(fn()=>$this->pay($p,1,$m,5000),'schválenou aktuální');self::assertSame(0,clubRewardPaid($p,1));}
 public function testWrongMovementDateRollsBackWholePayout():void {$p=$this->db();$v=$this->submit($p);$this->approve($p,$v);$m=$this->movement($p,-12500,'TEST-wrong-date');$this->denied(fn()=>clubRewardPay($p,1,['movement_id'=>$m,'amount_minor'=>5000,'paid_on'=>'2026-02-02','received_by'=>'TEST actual receiver','request_key'=>'TEST-wrong-date'],3,'TEST date mismatch proof',true),'Datum');self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM accounting_allocations')->fetchColumn());}
}
